DROP TABLE IF EXISTS `cropdex_users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `cropdex_users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(255) DEFAULT NULL,
  `password` varchar(255) DEFAULT NULL,
  `association_id` int(11) DEFAULT NULL,
  `access_level_id` int(11) DEFAULT NULL,
  `display_name` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `association_id` (`association_id`),
  KEY `access_level_id` (`access_level_id`),
  CONSTRAINT `cropdex_users_ibfk_1` FOREIGN KEY (`association_id`) REFERENCES `cropdex_associations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `cropdex_users_ibfk_2` FOREIGN KEY (`access_level_id`) REFERENCES `cropdex_access_levels` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

